// Audit UI/i18n complet, plusieurs corrections independantes livrees
// ensemble :
//
// 1) Messages d'erreur bruts (codes internes ou texte anglais brut de
// Supabase) affiches tels quels a la creation/invitation Duel, Duel XI et
// Groupe - remplaces par le message generique deja traduit dans les 3
// langues, comme le fait deja le reste de l'app.
//
// 2) Ecran Profil : popup d'upload d'avatar en erreur avait un titre
// anglais code en dur + un message brut (parfois un debug string avec
// taille en octets) - maintenant traduit dans les 3 langues, avec un
// message specifique et actionnable pour le cas "permission refusee".
//
// 3) Ecran Missions : 3 phrases restaient en francais meme en changeant
// de langue (l'appli a un vrai selecteur FR/EN/ES qui marchait pour tout
// le reste). Fix : deux cles fantomes ("_html") existaient deja dans le
// dictionnaire mais n'etaient jamais utilisees par l'ecran - remplacees
// par des cles texte simple, effectivement branchees cette fois.
//
// 4) Etiquettes nationalite/poste ("ATTAQUANT", "GARDIEN"...) restaient
// en francais quelle que soit la langue choisie, sur les 2 ecrans les
// plus joues (Devine le joueur, Collection). NAT_FR/POS_FR (uniquement
// francais) retires de engine.ts, remplaces par 61 nouvelles cles i18n
// (57 nationalites x 3 langues + 4 postes x 3 langues) et une fonction
// criterionLabel() dans gridDuel.ts pour que les en-tetes de la Grille
// restent aussi traduits (le libelle y etait fige au moment de generer
// la grille, avant meme de savoir dans quelle langue l'afficher).
//
// 5) Le clavier virtuel AZERTY (francais) etait duplique tel quel dans 9
// ecrans differents et s'affichait meme en anglais/espagnol, ou un
// clavier QWERTY serait attendu. Centralise dans un seul fichier
// (lib/keyboard.ts), qui bascule automatiquement selon la langue active.
//
// 6) Petite incoherence trouvee et corrigee au passage : le bouton retour
// du Defi du jour etait a la taille 20 au lieu de 22 comme les autres
// ecrans du meme type (Collection, Missions, Reglages, Boutique).
// Run from strikr-app/: node patch-i18n-audit-fixes.js
const fs = require('fs');
const path = require('path');

function write(rel, content) {
  const full = path.join(process.cwd(), rel);
  fs.writeFileSync(full, content);
  console.log('WROTE', rel);
}

write("src/screens/DuelScreen.tsx", "import React, { useEffect, useState } from 'react';\nimport { ActivityIndicator, Modal, Pressable, ScrollView, Text, TextInput, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport * as Clipboard from 'expo-clipboard';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useI18n } from '../i18n/i18n';\nimport { DUEL_TURN_SECONDS, useDuel } from '../game/useDuel';\nimport { useInterstitialAd } from '../game/useInterstitialAd';\nimport { criterionLabel } from '../game/gridDuel';\nimport { PLAYERS } from '../data/players';\nimport { stripAcc } from '../game/engine';\nimport HardShadowBox from '../components/HardShadowBox';\nimport ClubShield from '../components/ClubShield';\nimport { flagEmoji } from '../lib/flags';\nimport RulesModal from '../components/RulesModal';\nimport { useRulesModal } from '../lib/useRulesModal';\nimport { KEY_ROWS_BY_LANG } from '../lib/keyboard';\n\ninterface DuelScreenProps {\n  onBack?: () => void;\n  inviteUserId?: string;\n  inviteUserName?: string;\n  onInviteConsumed?: () => void;\n}\n\nexport default function DuelScreen({ onBack, inviteUserId, inviteUserName, onInviteConsumed }: DuelScreenProps) {\n  const { colors, accent, fonts } = useTheme();\n  const { t, lang } = useI18n();\n  const insets = useSafeAreaInsets();\n  const { duel, loading, myRole, createDuel, inviteDuel, respondInvite, cancelInvite, joinDuel, playCell, passTurn, forfeit, clearFinished, lastReward, rewardedToday, rewardedLimit } = useDuel();\n  const { recordRoundPlayed } = useInterstitialAd();\n  const rules = useRulesModal('grille');\n\n  // Came here via FriendsScreen's \"challenge\" button (passed down through the\n  // Jeux hub): send the invite once loading has settled and we know there's\n  // no active one already, then tell the hub to clear the param so\n  // refocusing this mode later doesn't refire it.\n  useEffect(() => {\n    if (!inviteUserId || loading || duel) return;\n    setMessage(null);\n    inviteDuel(inviteUserId, inviteUserName || '').then(({ error }) => {\n      // createDuel/inviteDuel only ever fail on 'not_authenticated' (can't\n      // really happen, this screen requires being signed in) or a raw\n      // Supabase error string — neither is meant for display, so always\n      // show the generic translated message instead of leaking either.\n      if (error) setMessage(t('error_generic'));\n    });\n    onInviteConsumed?.();\n  }, [inviteUserId, inviteUserName, loading, duel, inviteDuel, onInviteConsumed]);\n\n  const [joinCode, setJoinCode] = useState('');\n  const [busy, setBusy] = useState(false);\n  const [message, setMessage] = useState<string | null>(null);\n  const [copied, setCopied] = useState(false);\n  const [selectedCell, setSelectedCell] = useState<number | null>(null);\n  const [answer, setAnswer] = useState('');\n  const [cellError, setCellError] = useState<string | null>(null);\n  const [now, setNow] = useState(Date.now());\n\n  const updateAnswer = (next: string) => {\n    setAnswer(next);\n    setCellError(null);\n  };\n\n  // Per-turn countdown, ticked locally from turn_started_at. Only the player\n  // on the clock passes their own turn when it runs out — the other client\n  // is just watching and will pick up the resulting realtime update.\n  useEffect(() => {\n    if (!duel || duel.status !== 'active') return;\n    const id = setInterval(() => setNow(Date.now()), 1000);\n    return () => clearInterval(id);\n  }, [duel?.status, duel?.id]);\n\n  const secondsLeft =\n    duel && duel.status === 'active'\n      ? Math.max(0, DUEL_TURN_SECONDS - Math.floor((now - new Date(duel.turn_started_at).getTime()) / 1000))\n      : DUEL_TURN_SECONDS;\n\n  useEffect(() => {\n    if (!duel || duel.status !== 'active' || duel.turn !== myRole) return;\n    if (secondsLeft === 0) passTurn();\n  }, [secondsLeft, duel?.status, duel?.turn, myRole, passTurn]);\n\n  const onCreate = async () => {\n    setBusy(true);\n    setMessage(null);\n    const { error } = await createDuel();\n    setBusy(false);\n    if (error) setMessage(t('error_generic'));\n  };\n\n  const onJoin = async () => {\n    if (!joinCode.trim()) return;\n    setBusy(true);\n    setMessage(null);\n    const { error } = await joinDuel(joinCode.trim());\n    setBusy(false);\n    if (error) setMessage(t('duel_error_code'));\n    else setJoinCode('');\n  };\n\n  const copyCode = async () => {\n    if (!duel) return;\n    await Clipboard.setStringAsync(duel.code);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 1500);\n  };\n\n  const openCell = (index: number) => {\n    if (!duel || duel.status !== 'active' || duel.turn !== myRole || duel.cells[index].owner) return;\n    setSelectedCell(index);\n    setAnswer('');\n    setCellError(null);\n  };\n\n  const submitAnswer = async () => {\n    if (selectedCell === null || !answer.trim()) return;\n    const { error } = await playCell(selectedCell, answer.trim());\n    if (error) {\n      setCellError(error === 'player_used' ? t('duel_error_used') : t('duel_error_invalid'));\n      return;\n    }\n    setSelectedCell(null);\n    setAnswer('');\n    setCellError(null);\n  };\n\n  const suggestions =\n    answer.trim().length >= 2\n      ? PLAYERS.filter((p) => stripAcc(p.n.toLowerCase()).includes(stripAcc(answer.trim().toLowerCase()))).slice(0, 5)\n      : [];\n\n  // Every branch below gets the same optional \"back to hub\" chip pinned\n  // top-left and a \"?\" rules button pinned top-right, rather than\n  // threading them through each screen.\n  const withBack = (node: React.ReactElement, opts?: { hideRulesButton?: boolean }) => (\n    <View style={{ flex: 1 }}>\n      {node}\n      {onBack && (\n        <Pressable\n          onPress={onBack}\n          hitSlop={8}\n          style={{ position: 'absolute', top: insets.top + 14, left: 16, width: 30, height: 30, borderRadius: 999, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n        >\n          <Text style={{ fontFamily: fonts.display, fontSize: 14, color: colors.ink }}>←</Text>\n        </Pressable>\n      )}\n      {!opts?.hideRulesButton && (\n        <Pressable\n          onPress={rules.show}\n          hitSlop={8}\n          style={{ position: 'absolute', top: insets.top + 14, right: 16, width: 30, height: 30, borderRadius: 999, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n        >\n          <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>?</Text>\n        </Pressable>\n      )}\n      <RulesModal visible={rules.visible} onClose={rules.hide} title={t('rules_grille_title')} body={t('rules_grille_body')} />\n    </View>\n  );\n\n  if (loading) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.muted} />\n      </View>\n    );\n  }\n\n  // No duel yet: create or join one.\n  if (!duel) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n        <ScrollView contentContainerStyle={{ padding: 20, gap: 14 }}>\n          <Text style={{ fontFamily: fonts.display, fontSize: 26, color: colors.ink, letterSpacing: -0.5 }}>\n            {t('nav_duel')}\n          </Text>\n          <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, lineHeight: 18 }}>{t('duel_intro')}</Text>\n\n          <Pressable\n            onPress={onCreate}\n            disabled={busy}\n            style={{ padding: 16, backgroundColor: accent.coral, borderWidth: 2.5, borderColor: colors.border, borderRadius: 14, alignItems: 'center', opacity: busy ? 0.6 : 1 }}\n          >\n            {busy ? <ActivityIndicator color=\"#fff\" /> : <Text style={{ fontFamily: fonts.display, fontSize: 14, color: '#fff' }}>{t('duel_create')}</Text>}\n          </Pressable>\n\n          <View style={{ flexDirection: 'row', gap: 8 }}>\n            <TextInput\n              value={joinCode}\n              onChangeText={setJoinCode}\n              placeholder={t('duel_join_placeholder')}\n              placeholderTextColor={colors.muted}\n              autoCapitalize=\"characters\"\n              autoCorrect={false}\n              style={{ flex: 1, paddingVertical: 12, paddingHorizontal: 14, borderWidth: 2, borderColor: colors.border, borderRadius: 12, fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}\n            />\n            <Pressable onPress={onJoin} style={{ paddingHorizontal: 16, justifyContent: 'center', backgroundColor: accent.blue, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 12, color: '#fff' }}>{t('duel_join')}</Text>\n            </Pressable>\n          </View>\n\n          {message && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: colors.muted }}>{message}</Text>}\n        </ScrollView>\n      </View>\n    );\n  }\n\n  // Waiting for an opponent to join.\n  if (duel.status === 'waiting') {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <ActivityIndicator color={colors.muted} />\n        <Text style={{ fontFamily: fonts.display, fontSize: 18, color: colors.ink, textAlign: 'center' }}>{t('duel_waiting_title')}</Text>\n        <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: colors.muted }}>{t('duel_waiting_code_label')}</Text>\n        <Pressable onPress={copyCode} style={{ paddingVertical: 12, paddingHorizontal: 24, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n          <Text style={{ fontFamily: fonts.display, fontSize: 22, color: colors.ink, letterSpacing: 3 }}>{copied ? t('duel_copied') : duel.code}</Text>\n        </Pressable>\n        <Pressable onPress={forfeit} style={{ paddingVertical: 8, paddingHorizontal: 16 }}>\n          <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: colors.muted }}>{t('duel_cancel')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // I sent an invite and I'm waiting on the other person to respond.\n  if (duel.status === 'invited' && myRole === 'creator') {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <ActivityIndicator color={colors.muted} />\n        <Text style={{ fontFamily: fonts.display, fontSize: 18, color: colors.ink, textAlign: 'center' }}>\n          {t('duel_invite_waiting_title').replace('{name}', duel.opponent_name || '')}\n        </Text>\n        <Pressable onPress={cancelInvite} style={{ paddingVertical: 8, paddingHorizontal: 16 }}>\n          <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: colors.muted }}>{t('duel_cancel')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // Someone invited me — accept or decline.\n  if (duel.status === 'invited' && myRole === 'opponent') {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <Text style={{ fontSize: 40 }}>⚔️</Text>\n        <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink, textAlign: 'center' }}>\n          {t('duel_invite_received_title').replace('{name}', duel.creator_name || '')}\n        </Text>\n        <View style={{ flexDirection: 'row', gap: 10 }}>\n          <Pressable onPress={() => respondInvite(false)} style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink }}>{t('duel_invite_decline')}</Text>\n          </Pressable>\n          <Pressable onPress={() => respondInvite(true)} style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('duel_invite_accept')}</Text>\n          </Pressable>\n        </View>\n      </View>\n    );\n  }\n\n  // The other person declined (or the invite was cancelled) — only ever\n  // seen by the creator, since the decliner clears their own state locally.\n  if (duel.status === 'declined') {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <Text style={{ fontSize: 40 }}>😔</Text>\n        <Text style={{ fontFamily: fonts.display, fontSize: 18, color: colors.ink, textAlign: 'center' }}>\n          {t('duel_invite_declined_title').replace('{name}', duel.opponent_name || '')}\n        </Text>\n        <Pressable onPress={clearFinished} style={{ paddingVertical: 12, paddingHorizontal: 24, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n          <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('duel_new')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // Finished.\n  if (duel.status === 'finished') {\n    const won = duel.winner === myRole;\n    const title = duel.winner === 'draw' ? t('duel_draw_title') : won ? t('duel_win_title') : t('duel_lose_title');\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <Text style={{ fontSize: 48 }}>{duel.winner === 'draw' ? '🤝' : won ? '🏆' : '😔'}</Text>\n        <Text style={{ fontFamily: fonts.display, fontSize: 26, color: colors.ink }}>{title}</Text>\n        {(won || duel.winner === 'draw') && (\n          <Text style={{ fontFamily: fonts.mono, fontSize: 12, color: colors.muted }}>\n            {lastReward > 0 ? `+${lastReward} 💎` : `💎 ${rewardedToday}/${rewardedLimit} ${t('club_rewards_left')}`}\n          </Text>\n        )}\n        <Pressable onPress={() => recordRoundPlayed(clearFinished)} style={{ paddingVertical: 12, paddingHorizontal: 24, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n          <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('duel_new')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // Active gameplay.\n  const isMyTurn = duel.turn === myRole;\n  return withBack(\n    <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n      <View style={{ paddingHorizontal: 20, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>\n          <Text\n            style={{\n              fontFamily: fonts.display, fontSize: 14, color: isMyTurn ? accent.coral : colors.muted,\n            }}\n          >\n            {isMyTurn ? t('duel_your_turn') : t('duel_opponent_turn')}\n          </Text>\n          <View style={{ paddingVertical: 3, paddingHorizontal: 8, backgroundColor: secondsLeft <= 10 ? accent.wrongRed : colors.track, borderRadius: 999 }}>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: secondsLeft <= 10 ? '#fff' : colors.muted }}>⏱ {secondsLeft}s</Text>\n          </View>\n        </View>\n        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>\n          <Pressable onPress={rules.show} hitSlop={8} style={{ width: 22, height: 22, borderRadius: 999, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>?</Text>\n          </Pressable>\n          <Pressable onPress={forfeit}>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted }}>{t('duel_forfeit')}</Text>\n          </Pressable>\n        </View>\n      </View>\n\n      <View style={{ padding: 20 }}>\n        <View style={{ flexDirection: 'row' }}>\n          <View style={{ width: 78 }} />\n          {duel.grid.cols.map((c, i) => (\n            <View key={i} style={{ flex: 1, alignItems: 'center', paddingBottom: 6, gap: 3 }}>\n              {c.type === 'nat' && <Text style={{ fontSize: 28 }}>{flagEmoji(c.value)}</Text>}\n              {c.type === 'club' && <ClubShield name={c.value} size={34} />}\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 10, color: colors.ink, textAlign: 'center' }}>{criterionLabel(c, t)}</Text>\n            </View>\n          ))}\n        </View>\n        {duel.grid.rows.map((r, ri) => (\n          <View key={ri} style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6 }}>\n            <View style={{ width: 78, paddingRight: 6, alignItems: 'center', gap: 3 }}>\n              {r.type === 'club' && <ClubShield name={r.value} size={34} />}\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 10, color: colors.ink, textAlign: 'center' }} numberOfLines={2}>{criterionLabel(r, t)}</Text>\n            </View>\n            {duel.grid.cols.map((_, ci) => {\n              const index = ri * 3 + ci;\n              const cell = duel.cells[index];\n              const mine = cell.owner === myRole;\n              return (\n                <Pressable\n                  key={ci}\n                  onPress={() => openCell(index)}\n                  style={{ flex: 1, aspectRatio: 1, marginHorizontal: 3, borderRadius: 10, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center', backgroundColor: cell.owner ? (mine ? accent.mint : accent.wrongRed) : colors.card, padding: 4 }}\n                >\n                  {cell.owner ? (\n                    <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 9, color: '#1a1a1a', textAlign: 'center' }} numberOfLines={2}>{cell.name}</Text>\n                  ) : (\n                    <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.muted }}>+</Text>\n                  )}\n                </Pressable>\n              );\n            })}\n          </View>\n        ))}\n      </View>\n\n      <Modal visible={selectedCell !== null} transparent animationType=\"fade\" onRequestClose={() => setSelectedCell(null)}>\n        <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.45)', justifyContent: 'flex-end' }} onPress={() => setSelectedCell(null)}>\n          <Pressable style={{ backgroundColor: colors.bg, borderTopWidth: 2.5, borderColor: colors.border, borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: 20, paddingBottom: Math.max(20, insets.bottom + 12) }}>\n            <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, paddingVertical: 12, paddingHorizontal: 14 }}>\n              <Text numberOfLines={1} style={{ fontFamily: fonts.displayBold, fontSize: 14, color: answer ? colors.ink : colors.muted }}>\n                {answer || t('duel_answer_placeholder')}\n              </Text>\n            </View>\n            {suggestions.length > 0 && (\n              <View style={{ marginTop: 6, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, overflow: 'hidden' }}>\n                {suggestions.map((s) => (\n                  <Pressable key={s.n} onPress={() => updateAnswer(s.n)} style={{ paddingVertical: 9, paddingHorizontal: 14, borderBottomWidth: 1, borderBottomColor: 'rgba(0,0,0,.06)' }}>\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{s.n}</Text>\n                  </Pressable>\n                ))}\n              </View>\n            )}\n            {cellError && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: accent.coral, marginTop: 8 }}>{cellError}</Text>}\n\n            <View style={{ marginTop: 10, gap: 4 }}>\n              {KEY_ROWS_BY_LANG[lang].map((row, ri) => (\n                <View key={ri} style={{ flexDirection: 'row', gap: 4 }}>\n                  {ri === 2 && <View style={{ flex: 0.5 }} />}\n                  {row.split('').map((l) => (\n                    <Pressable\n                      key={l}\n                      onPress={() => updateAnswer(answer + l)}\n                      style={{ flex: 1, height: 38, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n                    >\n                      <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{l}</Text>\n                    </Pressable>\n                  ))}\n                  {ri === 2 && <View style={{ flex: 0.5 }} />}\n                </View>\n              ))}\n              <View style={{ flexDirection: 'row', gap: 4 }}>\n                <Pressable\n                  onPress={() => updateAnswer(answer.slice(0, -1))}\n                  style={{ flex: 1.4, height: 38, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n                >\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{t('game_backspace')}</Text>\n                </Pressable>\n                <Pressable\n                  onPress={() => updateAnswer(answer + ' ')}\n                  style={{ flex: 3, height: 38, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n                >\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{t('game_space')}</Text>\n                </Pressable>\n              </View>\n            </View>\n\n            <Pressable onPress={submitAnswer} style={{ marginTop: 12, paddingVertical: 12, backgroundColor: accent.coral, borderRadius: 12, alignItems: 'center' }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('duel_validate')}</Text>\n            </Pressable>\n          </Pressable>\n        </Pressable>\n      </Modal>\n    </View>,\n    { hideRulesButton: true }\n  );\n}\n");
write("src/screens/XIDuelScreen.tsx", "// \"XI Type\" duel: pick a famous match, challenge a friend, then take turns\n// naming the starting eleven — 45s per name, most correct wins. Turn-based\n// (unlike Mode Liste's duel, which races simultaneously), so this has its\n// own hook (useXIDuel) and screen rather than reusing GroupGameScreen.\nimport React, { useEffect, useRef, useState } from 'react';\nimport { ActivityIndicator, Pressable, ScrollView, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useI18n } from '../i18n/i18n';\nimport { XI_DUEL_TURN_SECONDS, useXIDuel } from '../game/useXIDuel';\nimport { useInterstitialAd } from '../game/useInterstitialAd';\nimport { XI_MATCHES } from '../data/xiMatches';\nimport { playerFull } from '../data/quizLists';\nimport { PLAYERS } from '../data/players';\nimport { useFriends } from '../state/friends';\nimport { stripAcc } from '../game/engine';\nimport RulesModal from '../components/RulesModal';\nimport { useRulesModal } from '../lib/useRulesModal';\nimport XIPitch from '../components/XIPitch';\nimport { KEY_ROWS_BY_LANG } from '../lib/keyboard';\n\nfunction norm(s: string): string {\n  return stripAcc(s.trim().toLowerCase()).replace(/[^a-z]/g, '');\n}\n\ninterface XIDuelScreenProps {\n  onBack?: () => void;\n  // Set when arriving from FriendsScreen's \"challenge\" picker: fires the\n  // invite straight to that friend as soon as a match is chosen, instead\n  // of making the challenger pick them again from the list below.\n  inviteUserId?: string;\n  inviteUserName?: string;\n  onInviteConsumed?: () => void;\n}\n\nexport default function XIDuelScreen({ onBack, inviteUserId, inviteUserName, onInviteConsumed }: XIDuelScreenProps) {\n  const { colors, accent, fonts } = useTheme();\n  const { t, lang } = useI18n();\n  const insets = useSafeAreaInsets();\n  const rules = useRulesModal('duel_xi');\n  const { friends, loading: friendsLoading } = useFriends();\n  const {\n    duel, match, loading, myRole,\n    inviteXIDuel, respondInvite, cancelInvite, guessName, passTurn, forfeit, clearFinished,\n    lastReward, rewardedToday, rewardedLimit,\n  } = useXIDuel();\n  const { recordRoundPlayed } = useInterstitialAd();\n\n  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);\n  const [inviting, setInviting] = useState<string | null>(null);\n  const [message, setMessage] = useState<string | null>(null);\n  const [answer, setAnswer] = useState('');\n  const [answerError, setAnswerError] = useState<string | null>(null);\n  const [now, setNow] = useState(Date.now());\n\n  const updateAnswer = (next: string) => {\n    setAnswer(next);\n    setAnswerError(null);\n  };\n\n  // Per-turn countdown, ticked locally from turn_started_at. Only the player\n  // on the clock passes their own turn when it runs out — the other client\n  // is just watching and will pick up the resulting realtime update.\n  useEffect(() => {\n    if (!duel || duel.status !== 'active') return;\n    const id = setInterval(() => setNow(Date.now()), 1000);\n    return () => clearInterval(id);\n  }, [duel?.status, duel?.id]);\n\n  const secondsLeft =\n    duel && duel.status === 'active'\n      ? Math.max(0, XI_DUEL_TURN_SECONDS - Math.floor((now - new Date(duel.turn_started_at).getTime()) / 1000))\n      : XI_DUEL_TURN_SECONDS;\n\n  useEffect(() => {\n    if (!duel || duel.status !== 'active' || duel.turn !== myRole) return;\n    if (secondsLeft === 0) passTurn();\n  }, [secondsLeft, duel?.status, duel?.turn, myRole, passTurn]);\n\n  const sendInvite = async (friendId: string, friendName: string) => {\n    if (!selectedMatchId) return;\n    const m = XI_MATCHES.find((x) => x.id === selectedMatchId);\n    if (!m) return;\n    setInviting(friendId);\n    setMessage(null);\n    const { error } = await inviteXIDuel(friendId, friendName, m.id, m.title);\n    setInviting(null);\n    // Only ever fails on 'not_authenticated' or a raw Supabase error string,\n    // neither meant for display — always the generic translated message.\n    if (error) setMessage(t('error_generic'));\n  };\n\n  // Ref (not state) so this can only ever fire once per mount, regardless\n  // of how many times the effect re-runs while waiting on `duel` to update\n  // from the realtime subscription.\n  const invitedOnceRef = useRef(false);\n  useEffect(() => {\n    if (!inviteUserId || !selectedMatchId || invitedOnceRef.current) return;\n    invitedOnceRef.current = true;\n    sendInvite(inviteUserId, inviteUserName || '');\n    onInviteConsumed?.();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [inviteUserId, selectedMatchId]);\n\n  const submitAnswer = async () => {\n    if (!answer.trim()) return;\n    const { error } = await guessName(answer.trim());\n    if (error) {\n      setAnswerError(t('xi_duel_error_invalid'));\n      return;\n    }\n    setAnswer('');\n    setAnswerError(null);\n  };\n\n  // Suggests from the full player database (not just this match's 11) so\n  // the list helps with spelling without doubling as an answer key — a\n  // name showing up here no longer means it's necessarily correct.\n  const foundNamesNorm = new Set(\n    match ? (duel?.found ?? []).map((f) => norm(playerFull(match.players[f.index]))) : []\n  );\n\n  const suggestions =\n    match && answer.trim().length >= 2\n      ? PLAYERS\n          .map((p) => p.n)\n          .filter((n) => !foundNamesNorm.has(norm(n)))\n          .filter((n) => norm(n).includes(norm(answer.trim())))\n          .slice(0, 5)\n      : [];\n\n  const withBack = (node: React.ReactElement) => (\n    <View style={{ flex: 1 }}>\n      {node}\n      {onBack && (\n        <Pressable\n          onPress={onBack}\n          hitSlop={8}\n          style={{ position: 'absolute', top: insets.top + 14, left: 16, width: 30, height: 30, borderRadius: 999, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n        >\n          <Text style={{ fontFamily: fonts.display, fontSize: 14, color: colors.ink }}>←</Text>\n        </Pressable>\n      )}\n      <Pressable\n        onPress={rules.show}\n        hitSlop={8}\n        style={{ position: 'absolute', top: insets.top + 14, right: 16, width: 30, height: 30, borderRadius: 999, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n      >\n        <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>?</Text>\n      </Pressable>\n      <RulesModal visible={rules.visible} onClose={rules.hide} title={t('rules_xi_title')} body={t('rules_xi_body')} />\n    </View>\n  );\n\n  if (loading) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.muted} />\n      </View>\n    );\n  }\n\n  // No duel yet: pick a match, then a friend to challenge.\n  if (!duel) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n        <ScrollView contentContainerStyle={{ padding: 20, gap: 14 }}>\n          <Text style={{ fontFamily: fonts.display, fontSize: 26, color: colors.ink, letterSpacing: -0.5 }}>{t('jeux_game_xi')}</Text>\n          <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, lineHeight: 18 }}>{t('xi_duel_intro')}</Text>\n\n          <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1 }}>{t('xi_duel_pick_match')}</Text>\n          <View style={{ gap: 8 }}>\n            {XI_MATCHES.map((m) => (\n              <Pressable\n                key={m.id}\n                onPress={() => setSelectedMatchId(m.id)}\n                style={{\n                  padding: 14, borderRadius: 12, borderWidth: 2, borderColor: colors.border,\n                  backgroundColor: selectedMatchId === m.id ? accent.coral : colors.card,\n                }}\n              >\n                <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: selectedMatchId === m.id ? '#fff' : colors.ink }}>{m.title}</Text>\n              </Pressable>\n            ))}\n          </View>\n\n          {selectedMatchId && (\n            <>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1, marginTop: 6 }}>{t('xi_duel_pick_friend')}</Text>\n              {friendsLoading ? (\n                <ActivityIndicator color={colors.muted} />\n              ) : friends.length === 0 ? (\n                <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted }}>{t('friends_none')}</Text>\n              ) : (\n                <View style={{ gap: 8 }}>\n                  {friends.map((f) => (\n                    <Pressable\n                      key={f.id}\n                      onPress={() => sendInvite(f.id, f.display_name)}\n                      disabled={!!inviting}\n                      style={{ flexDirection: 'row', alignItems: 'center', gap: 10, padding: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, opacity: inviting && inviting !== f.id ? 0.5 : 1 }}\n                    >\n                      <Text style={{ flex: 1, fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{f.display_name}</Text>\n                      {inviting === f.id ? <ActivityIndicator color={colors.muted} /> : <Text style={{ fontSize: 16 }}>⚔️</Text>}\n                    </Pressable>\n                  ))}\n                </View>\n              )}\n            </>\n          )}\n\n          {message && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: colors.muted }}>{message}</Text>}\n        </ScrollView>\n      </View>\n    );\n  }\n\n  // I sent an invite and I'm waiting on the other person to respond.\n  if (duel.status === 'invited' && myRole === 'creator') {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <ActivityIndicator color={colors.muted} />\n        <Text style={{ fontFamily: fonts.display, fontSize: 18, color: colors.ink, textAlign: 'center' }}>\n          {t('duel_invite_waiting_title').replace('{name}', duel.opponent_name || '')}\n        </Text>\n        <Pressable onPress={cancelInvite} style={{ paddingVertical: 8, paddingHorizontal: 16 }}>\n          <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: colors.muted }}>{t('duel_cancel')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // Someone invited me — accept or decline.\n  if (duel.status === 'invited' && myRole === 'opponent') {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <Text style={{ fontSize: 40 }}>🎽</Text>\n        <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink, textAlign: 'center' }}>\n          {t('duel_invite_received_title').replace('{name}', duel.creator_name || '')}\n        </Text>\n        <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 13, color: colors.muted, textAlign: 'center' }}>{duel.match_title}</Text>\n        <View style={{ flexDirection: 'row', gap: 10 }}>\n          <Pressable onPress={() => respondInvite(false)} style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink }}>{t('duel_invite_decline')}</Text>\n          </Pressable>\n          <Pressable onPress={() => respondInvite(true)} style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('duel_invite_accept')}</Text>\n          </Pressable>\n        </View>\n      </View>\n    );\n  }\n\n  // The other person declined (or the invite was cancelled) — only ever\n  // seen by the creator, since the decliner clears their own state locally.\n  if (duel.status === 'declined') {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <Text style={{ fontSize: 40 }}>😔</Text>\n        <Text style={{ fontFamily: fonts.display, fontSize: 18, color: colors.ink, textAlign: 'center' }}>\n          {t('duel_invite_declined_title').replace('{name}', duel.opponent_name || '')}\n        </Text>\n        <Pressable onPress={clearFinished} style={{ paddingVertical: 12, paddingHorizontal: 24, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n          <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('duel_new')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // Finished.\n  if (duel.status === 'finished') {\n    const won = duel.winner === myRole;\n    const myScore = myRole === 'creator' ? duel.creator_score : duel.opponent_score;\n    const otherScore = myRole === 'creator' ? duel.opponent_score : duel.creator_score;\n    const title = duel.winner === 'draw' ? t('duel_draw_title') : won ? t('duel_win_title') : t('duel_lose_title');\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <Text style={{ fontSize: 48 }}>{duel.winner === 'draw' ? '🤝' : won ? '🏆' : '😔'}</Text>\n        <Text style={{ fontFamily: fonts.display, fontSize: 26, color: colors.ink }}>{title}</Text>\n        <Text style={{ fontFamily: fonts.displayBold, fontSize: 16, color: colors.ink }}>{myScore} — {otherScore}</Text>\n        {(won || duel.winner === 'draw') && (\n          <Text style={{ fontFamily: fonts.mono, fontSize: 12, color: colors.muted }}>\n            {lastReward > 0 ? `+${lastReward} 💎` : `💎 ${rewardedToday}/${rewardedLimit} ${t('club_rewards_left')}`}\n          </Text>\n        )}\n        <Pressable onPress={() => recordRoundPlayed(clearFinished)} style={{ paddingVertical: 12, paddingHorizontal: 24, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n          <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('duel_new')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // Active gameplay.\n  if (!match) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.muted} />\n      </View>\n    );\n  }\n  const isMyTurn = duel.turn === myRole;\n  const myScore = myRole === 'creator' ? duel.creator_score : duel.opponent_score;\n  const otherScore = myRole === 'creator' ? duel.opponent_score : duel.creator_score;\n  const foundByIndex = new Map(duel.found.map((f) => [f.index, f]));\n\n  return withBack(\n    <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n      <View style={{ paddingHorizontal: 20 }}>\n        <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.ink }} numberOfLines={2}>{duel.match_title}</Text>\n        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginTop: 8 }}>\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 14, color: isMyTurn ? accent.coral : colors.muted }}>\n              {isMyTurn ? t('duel_your_turn') : t('duel_opponent_turn')}\n            </Text>\n            <View style={{ paddingVertical: 3, paddingHorizontal: 8, backgroundColor: secondsLeft <= 10 ? accent.wrongRed : colors.track, borderRadius: 999 }}>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: secondsLeft <= 10 ? '#fff' : colors.muted }}>⏱ {secondsLeft}s</Text>\n            </View>\n          </View>\n          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{myScore} — {otherScore}</Text>\n            <Pressable onPress={forfeit}>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted }}>{t('duel_forfeit')}</Text>\n            </Pressable>\n          </View>\n        </View>\n      </View>\n\n      <ScrollView contentContainerStyle={{ paddingHorizontal: 20, paddingVertical: 14 }} style={{ flex: 1 }}>\n        <XIPitch\n          players={match.players}\n          foundIndexes={Array.from(foundByIndex.keys())}\n          colorForIndex={(i) => {\n            const f = foundByIndex.get(i);\n            if (!f) return undefined;\n            return f.by === myRole ? accent.mint : accent.wrongRed;\n          }}\n        />\n      </ScrollView>\n\n      <View style={{ paddingHorizontal: 20, paddingBottom: Math.max(12, insets.bottom + 8) }}>\n        <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, paddingVertical: 12, paddingHorizontal: 14, opacity: isMyTurn ? 1 : 0.5 }}>\n          <Text numberOfLines={1} style={{ fontFamily: fonts.displayBold, fontSize: 14, color: answer ? colors.ink : colors.muted }}>\n            {answer || t('duel_answer_placeholder')}\n          </Text>\n        </View>\n        {suggestions.length > 0 && isMyTurn && (\n          <View style={{ marginTop: 6, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, overflow: 'hidden' }}>\n            {suggestions.map((s) => (\n              <Pressable key={playerFull(s)} onPress={() => updateAnswer(playerFull(s))} style={{ paddingVertical: 9, paddingHorizontal: 14, borderBottomWidth: 1, borderBottomColor: 'rgba(0,0,0,.06)' }}>\n                <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{playerFull(s)}</Text>\n              </Pressable>\n            ))}\n          </View>\n        )}\n        {answerError && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: accent.coral, marginTop: 8 }}>{answerError}</Text>}\n\n        {isMyTurn && (\n          <>\n            <View style={{ marginTop: 10, gap: 4 }}>\n              {KEY_ROWS_BY_LANG[lang].map((row, ri) => (\n                <View key={ri} style={{ flexDirection: 'row', gap: 4 }}>\n                  {ri === 2 && <View style={{ flex: 0.5 }} />}\n                  {row.split('').map((l) => (\n                    <Pressable\n                      key={l}\n                      onPress={() => updateAnswer(answer + l)}\n                      style={{ flex: 1, height: 38, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n                    >\n                      <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{l}</Text>\n                    </Pressable>\n                  ))}\n                  {ri === 2 && <View style={{ flex: 0.5 }} />}\n                </View>\n              ))}\n              <View style={{ flexDirection: 'row', gap: 4 }}>\n                <Pressable\n                  onPress={() => updateAnswer(answer.slice(0, -1))}\n                  style={{ flex: 1.4, height: 38, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n                >\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{t('game_backspace')}</Text>\n                </Pressable>\n                <Pressable\n                  onPress={() => updateAnswer(answer + ' ')}\n                  style={{ flex: 3, height: 38, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n                >\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{t('game_space')}</Text>\n                </Pressable>\n              </View>\n            </View>\n            <Pressable onPress={submitAnswer} style={{ marginTop: 12, paddingVertical: 12, backgroundColor: accent.coral, borderRadius: 12, alignItems: 'center' }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('duel_validate')}</Text>\n            </Pressable>\n          </>\n        )}\n      </View>\n    </View>\n  );\n}\n");
write("src/screens/GroupGameScreen.tsx", "// Shared screen for Groupe (up to 4 invites) and Duel (1 invite) race modes,\n// across \"Devine le joueur\" (main), \"Devine le club\" (club), \"Mode Liste\"\n// (liste), and \"Grille\" (grille) — see useGroupGame for the lobby/sync/\n// reward model this sits on top of. Grille also keeps its separate\n// turn-based 1v1 DuelScreen, unrelated to this one.\nimport React, { useEffect, useRef, useState } from 'react';\nimport { ActivityIndicator, Image, Modal, Pressable, ScrollView, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useI18n } from '../i18n/i18n';\nimport { useAuth } from '../state/auth';\nimport { useFriends } from '../state/friends';\nimport { GroupGameType, useGroupGame } from '../game/useGroupGame';\nimport { useInterstitialAd } from '../game/useInterstitialAd';\nimport { PLAYERS } from '../data/players';\nimport { Level, clubColor, clubInit, matchesGuess, stripAcc } from '../game/engine';\nimport { MAX_GUESSES, ClubGuessRow, compareClubGuess, resolveClubGuess } from '../game/useClubGuess';\nimport { matchesCriteria, criterionLabel } from '../game/gridDuel';\nimport { CLUB_DATA } from '../data/clubData';\nimport { QUIZ_LISTS, QuizDifficulty, playerFull, playerBase, playerPhoto } from '../data/quizLists';\nimport { XI_MATCHES } from '../data/xiMatches';\nimport { flagEmoji } from '../lib/flags';\nimport { getClubLogo } from '../lib/wikiLookup';\nimport ClubShield from '../components/ClubShield';\nimport RevealCard from '../components/RevealCard';\nimport HardShadowBox from '../components/HardShadowBox';\nimport PlayerPortrait from '../components/PlayerPortrait';\nimport XIPitch from '../components/XIPitch';\nimport RulesModal from '../components/RulesModal';\nimport { useRulesModal } from '../lib/useRulesModal';\nimport { KEY_ROWS_BY_LANG } from '../lib/keyboard';\n\nconst DURATIONS = [60, 90, 120, 180];\nconst LEVEL_META: Record<Level, { icon: string; labelKey: string }> = {\n  easy: { icon: '🟢', labelKey: 'quiz_difficulty_easy' },\n  medium: { icon: '🟡', labelKey: 'quiz_difficulty_medium' },\n  hard: { icon: '🔴', labelKey: 'quiz_difficulty_hard' },\n};\nconst CREST_SIZE = 96;\n\ninterface GroupGameScreenProps {\n  onBack?: () => void;\n  gameType: GroupGameType;\n  variant: 'duel' | 'group';\n  // 'xi' reuses gameType='liste' end to end (same DB game_type, same race\n  // mechanic) but points the creator's list picker at XI_MATCHES (\"XI Type\")\n  // instead of QUIZ_LISTS (\"Mode Liste\") — no schema change needed since the\n  // list content itself is client-side data either way.\n  listPool?: 'liste' | 'xi';\n  // Set when arriving from FriendsScreen's \"challenge\" picker: pre-selects\n  // that friend in the lobby instead of making the challenger pick them\n  // again from the full friends list they were just looking at.\n  inviteUserId?: string;\n  inviteUserName?: string;\n  onInviteConsumed?: () => void;\n}\n\nfunction Crest({ name, revealFraction }: { name: string; revealFraction: number }) {\n  const { colors, fonts } = useTheme();\n  const [url, setUrl] = useState<string | null>(null);\n  useEffect(() => {\n    let cancelled = false;\n    setUrl(null);\n    getClubLogo(name).then((u) => {\n      if (!cancelled) setUrl(u);\n    });\n    return () => {\n      cancelled = true;\n    };\n  }, [name]);\n  if (!url) {\n    return (\n      <View style={{ width: CREST_SIZE, height: CREST_SIZE, borderRadius: 18, backgroundColor: clubColor(name), alignItems: 'center', justifyContent: 'center' }}>\n        <Text style={{ fontFamily: fonts.display, fontSize: 30, color: '#fff' }}>{clubInit(name)}</Text>\n      </View>\n    );\n  }\n  const revealedWidth = Math.max(14, CREST_SIZE * revealFraction);\n  return (\n    <View style={{ width: CREST_SIZE, height: CREST_SIZE, borderRadius: 18, backgroundColor: colors.card, borderWidth: 2.5, borderColor: colors.border, overflow: 'hidden', alignItems: 'center', justifyContent: 'center' }}>\n      <View style={{ width: revealedWidth, height: CREST_SIZE, overflow: 'hidden' }}>\n        <Image source={{ uri: url }} style={{ width: CREST_SIZE, height: CREST_SIZE, transform: [{ scaleX: revealFraction >= 1 ? 1 : -1 }] }} resizeMode=\"contain\" />\n      </View>\n    </View>\n  );\n}\n\nfunction Chip({ icon, value, match, label }: { icon: string; value: string; match: boolean | null; label: string }) {\n  const { colors, accent, fonts } = useTheme();\n  const bg = match === true ? accent.mint : colors.card;\n  return (\n    <View style={{ alignItems: 'center', gap: 2, flex: 1 }}>\n      <View style={{ width: 44, height: 44, borderRadius: 999, backgroundColor: bg, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n        <Text style={{ fontSize: 13 }}>{icon}</Text>\n        <Text style={{ fontFamily: fonts.displayBold, fontSize: 8, color: colors.ink }} numberOfLines={1}>{value}</Text>\n      </View>\n      <Text style={{ fontFamily: fonts.mono, fontSize: 7, color: colors.muted, letterSpacing: 0.5 }}>{label}</Text>\n    </View>\n  );\n}\n\nfunction ClubGuessChips({ row }: { row: ClubGuessRow }) {\n  const { t } = useI18n();\n  const { fonts, colors } = useTheme();\n  const compareIcon = (c: 'match' | 'up' | 'down') => (c === 'match' ? '✓' : c === 'up' ? '↑' : '↓');\n  return (\n    <View style={{ marginBottom: 8 }}>\n      <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink, marginBottom: 4, textAlign: 'center' }}>{row.name}</Text>\n      <View style={{ flexDirection: 'row', gap: 3 }}>\n        <Chip icon={flagEmoji(row.nat)} value={row.nat} match={row.natMatch} label={t('club_chip_nat')} />\n        <Chip icon={compareIcon(row.foundedCompare)} value={String(row.founded)} match={row.foundedCompare === 'match'} label={t('club_chip_est')} />\n        <Chip icon={compareIcon(row.capacityCompare)} value={`${Math.round(row.capacity / 1000)}k`} match={row.capacityCompare === 'match'} label={t('club_chip_cap')} />\n        <Chip icon={row.direction} value=\"\" match={null} label={t('club_chip_dir')} />\n        <Chip icon=\"📍\" value={`${row.distanceKm}`} match={row.distanceKm === 0} label={t('club_chip_dist')} />\n      </View>\n    </View>\n  );\n}\n\nexport default function GroupGameScreen({\n  onBack,\n  gameType,\n  variant,\n  listPool = 'liste',\n  inviteUserId,\n  inviteUserName,\n  onInviteConsumed,\n}: GroupGameScreenProps) {\n  const { colors, accent, fonts } = useTheme();\n  const { t, lang } = useI18n();\n  const insets = useSafeAreaInsets();\n  const rules = useRulesModal(listPool === 'xi' ? 'group_xi' : variant === 'duel' ? `duel_${gameType}` : 'group');\n  const { user } = useAuth();\n  const { friends, loading: friendsLoading } = useFriends();\n  const {\n    game,\n    players,\n    loading,\n    mysteryPlayer,\n    mysteryClub,\n    mysteryList,\n    grid,\n    isCreator,\n    createGroup,\n    respondInvite,\n    cancelLobby,\n    startRound,\n    submitResult,\n    finishGame,\n    leaveFinished,\n    lastReward,\n  } = useGroupGame();\n  const { recordRoundPlayed } = useInterstitialAd();\n\n  const maxFriends = variant === 'duel' ? 1 : 4;\n  const [selectedFriendIds, setSelectedFriendIds] = useState<string[]>([]);\n  const [roundSeconds, setRoundSeconds] = useState(90);\n  const [level, setLevel] = useState<Level>('medium');\n  const [listDifficulty, setListDifficulty] = useState<QuizDifficulty>('easy');\n  const [busy, setBusy] = useState(false);\n  const [createError, setCreateError] = useState<string | null>(null);\n  const autoInviteFiredRef = useRef(false);\n\n  // Arrived via FriendsScreen's \"challenge\" picker with a friend already\n  // chosen: pre-select them (there's only ever one slot in a duel lobby)\n  // instead of making the challenger find them again in the list below.\n  useEffect(() => {\n    if (!inviteUserId || loading || game) return;\n    setSelectedFriendIds([inviteUserId]);\n    onInviteConsumed?.();\n  }, [inviteUserId, loading, game, onInviteConsumed]);\n\n  // A 1-on-1 challenge from FriendsScreen shouldn't need a \"create the\n  // room\" tap like the up-to-4 Groupe flow does — send the invite the\n  // moment we land here, same as DuelScreen/XIDuelScreen already do for\n  // Grille/XI Type challenges.\n  useEffect(() => {\n    if (variant !== 'duel' || !inviteUserId || loading || game || autoInviteFiredRef.current) return;\n    autoInviteFiredRef.current = true;\n    setCreateError(null);\n    createGroup([inviteUserId], [inviteUserName || ''], roundSeconds, gameType).then(({ error }) => {\n      // Only ever a raw internal slug or a raw Supabase error string,\n      // neither meant for display — always the generic translated message.\n      if (error) setCreateError(t('error_generic'));\n    });\n  }, [variant, inviteUserId, inviteUserName, loading, game, roundSeconds, gameType, createGroup]);\n\n  // Local per-round play state — only reported back via submitResult() at\n  // solve or timeout, so other players never see live guesses, just the\n  // eventual result. Only the fields relevant to `gameType` get used.\n  const [answer, setAnswer] = useState('');\n  const [wrongList, setWrongList] = useState<string[]>([]);\n  const [revealed, setRevealed] = useState(0);\n  const [clubGuesses, setClubGuesses] = useState<ClubGuessRow[]>([]);\n  const [foundIndexes, setFoundIndexes] = useState<number[]>([]);\n  const [grilleCells, setGrilleCells] = useState<(string | null)[]>(Array(9).fill(null));\n  const [grilleUsedPlayers, setGrilleUsedPlayers] = useState<string[]>([]);\n  const [grilleSelectedCell, setGrilleSelectedCell] = useState<number | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [solved, setSolved] = useState(false);\n  // Distinct from `solved`: club can run out of its 6 guesses without ever\n  // finding the mystery club — that player is done playing too (same\n  // \"waiting for the round to end\" screen), but it isn't a win, so it needs\n  // its own flag rather than overloading `solved` and showing \"Found it!\".\n  const [outOfAttempts, setOutOfAttempts] = useState(false);\n  const [now, setNow] = useState(Date.now());\n  const handledRoundRef = useRef<string | null>(null);\n\n  const myRow = game ? players.find((p) => p.user_id === user?.id) : undefined;\n\n  useEffect(() => {\n    if (game && game.status === 'active' && handledRoundRef.current !== game.id) {\n      setAnswer('');\n      setWrongList([]);\n      setClubGuesses([]);\n      setFoundIndexes([]);\n      setGrilleCells(Array(9).fill(null));\n      setGrilleUsedPlayers([]);\n      setGrilleSelectedCell(null);\n      setError(null);\n      setSolved(false);\n      setOutOfAttempts(false);\n      if (gameType === 'main' && mysteryPlayer) setRevealed(Math.max(1, Math.min(3, mysteryPlayer.clubs.length - 2)));\n    }\n  }, [game?.id, game?.status, mysteryPlayer, gameType]);\n\n  useEffect(() => {\n    if (!game || game.status !== 'active') return;\n    const id = setInterval(() => setNow(Date.now()), 1000);\n    return () => clearInterval(id);\n  }, [game?.status, game?.id]);\n\n  const secondsLeft =\n    game && game.status === 'active' && game.started_at\n      ? Math.max(0, game.round_seconds - Math.floor((now - new Date(game.started_at).getTime()) / 1000))\n      : 0;\n\n  // Whoever's local countdown hits zero first reports (if not already\n  // solved) and flips the shared row — see useGroupGame.finishGame for the\n  // guard that makes a near-simultaneous second call harmless.\n  useEffect(() => {\n    if (!game || game.status !== 'active') return;\n    if (secondsLeft > 0) return;\n    if (handledRoundRef.current === game.id) return;\n    handledRoundRef.current = game.id;\n    if (!solved && !outOfAttempts) {\n      if (gameType === 'liste') submitResult({ foundCount: foundIndexes.length, solved: false });\n      else if (gameType === 'grille') submitResult({ foundCount: grilleCells.filter((c) => c).length, solved: false });\n      else submitResult({ attempts: gameType === 'club' ? clubGuesses.length : wrongList.length, elapsedMs: null, solved: false });\n    }\n    finishGame();\n  }, [\n    secondsLeft,\n    game?.id,\n    game?.status,\n    solved,\n    outOfAttempts,\n    gameType,\n    wrongList.length,\n    clubGuesses.length,\n    foundIndexes.length,\n    grilleCells,\n    submitResult,\n    finishGame,\n  ]);\n\n  const toggleFriend = (id: string) => {\n    setSelectedFriendIds((prev) => {\n      if (prev.includes(id)) return prev.filter((x) => x !== id);\n      if (maxFriends === 1) return [id];\n      return prev.length < maxFriends ? [...prev, id] : prev;\n    });\n  };\n\n  const handleCreate = async () => {\n    if (!selectedFriendIds.length || busy) return;\n    setBusy(true);\n    setCreateError(null);\n    const names = selectedFriendIds.map((id) => friends.find((f) => f.id === id)?.display_name || '');\n    const { error } = await createGroup(selectedFriendIds, names, roundSeconds, gameType);\n    if (error) setCreateError(t('error_generic'));\n    setBusy(false);\n  };\n\n  const handleStartMain = async () => {\n    if (busy) return;\n    setBusy(true);\n    await startRound({ level });\n    setBusy(false);\n  };\n  const handleStartClub = async () => {\n    if (busy) return;\n    setBusy(true);\n    await startRound();\n    setBusy(false);\n  };\n  const handleStartListe = async (listId: string) => {\n    if (busy) return;\n    setBusy(true);\n    await startRound({ listId });\n    setBusy(false);\n  };\n  const handleStartGrille = async () => {\n    if (busy) return;\n    setBusy(true);\n    await startRound();\n    setBusy(false);\n  };\n\n  const submitMainGuess = () => {\n    if (!mysteryPlayer || solved || !game || game.status !== 'active' || !answer.trim()) return;\n    if (matchesGuess(mysteryPlayer, answer)) {\n      const attempt = wrongList.length + 1;\n      const elapsed = game.started_at ? Date.now() - new Date(game.started_at).getTime() : null;\n      setSolved(true);\n      setRevealed(mysteryPlayer.clubs.length);\n      setAnswer('');\n      submitResult({ attempts: attempt, elapsedMs: elapsed, solved: true });\n    } else {\n      setWrongList((prev) => [...prev, answer.trim()]);\n      setRevealed((prev) => Math.min(prev + 1, mysteryPlayer.clubs.length));\n      setAnswer('');\n    }\n  };\n\n  const submitClubGuess = () => {\n    if (!mysteryClub || solved || outOfAttempts || !game || game.status !== 'active' || !answer.trim()) return;\n    const name = resolveClubGuess(answer);\n    if (!name) {\n      setError(t('club_error_unknown'));\n      return;\n    }\n    if (clubGuesses.some((g) => g.name === name)) {\n      setError(t('club_error_used'));\n      return;\n    }\n    const row = compareClubGuess(name, mysteryClub);\n    if (!row) {\n      setError(t('club_error_unknown'));\n      return;\n    }\n    const nextGuesses = [row, ...clubGuesses];\n    setClubGuesses(nextGuesses);\n    setAnswer('');\n    setError(null);\n    const won = name === mysteryClub;\n    if (won) {\n      const elapsed = game.started_at ? Date.now() - new Date(game.started_at).getTime() : null;\n      setSolved(true);\n      submitResult({ attempts: nextGuesses.length, elapsedMs: elapsed, solved: true });\n    } else if (nextGuesses.length >= MAX_GUESSES) {\n      setOutOfAttempts(true);\n      submitResult({ attempts: nextGuesses.length, elapsedMs: null, solved: false });\n    }\n  };\n\n  // Letters only: the on-screen keyboard has no hyphen/apostrophe keys, but\n  // real surnames do (\"Alexander-Arnold\", \"Guivarc'h\") — without this, those\n  // players could never be typed correctly no matter what's entered.\n  const normListeName = (s: string) => stripAcc(s.toLowerCase()).replace(/[^a-z]/g, '');\n\n  const submitListeGuess = () => {\n    if (!mysteryList || solved || !game || game.status !== 'active' || !answer.trim()) return;\n    const input = normListeName(answer.trim());\n    const baseCounts = new Map<string, number>();\n    mysteryList.players.forEach((p) => {\n      const b = normListeName(playerBase(p));\n      baseCounts.set(b, (baseCounts.get(b) || 0) + 1);\n    });\n    const idx = mysteryList.players.findIndex((p, i) => {\n      if (foundIndexes.includes(i)) return false;\n      const full = normListeName(playerFull(p));\n      const base = normListeName(playerBase(p));\n      if (input === full) return true;\n      if (input === base && (baseCounts.get(base) || 0) === 1) return true;\n      return false;\n    });\n    if (idx === -1) {\n      setError(t('club_error_unknown'));\n      return;\n    }\n    const nextFound = [...foundIndexes, idx];\n    setFoundIndexes(nextFound);\n    setAnswer('');\n    setError(null);\n    if (nextFound.length === mysteryList.players.length) {\n      setSolved(true);\n      submitResult({ foundCount: nextFound.length, solved: true });\n    }\n  };\n\n  // Grille uses a tap-a-cell-then-type modal (like SoloGridScreen) rather\n  // than the single shared answer bar the other three games use, so it gets\n  // its own submit function called from that modal instead of submitGuess().\n  const submitGrilleCell = () => {\n    if (!grid || grilleSelectedCell === null || !game || game.status !== 'active' || !answer.trim()) return;\n    const ri = Math.floor(grilleSelectedCell / 3);\n    const ci = grilleSelectedCell % 3;\n    const rowC = grid.rows[ri];\n    const colC = grid.cols[ci];\n    const found = matchesCriteria(answer, rowC, colC);\n    if (!found) {\n      setError(t('duel_error_invalid'));\n      return;\n    }\n    if (grilleUsedPlayers.includes(found.n)) {\n      setError(t('duel_error_used'));\n      return;\n    }\n    const nextCells = grilleCells.slice();\n    nextCells[grilleSelectedCell] = found.n;\n    setGrilleCells(nextCells);\n    setGrilleUsedPlayers((prev) => [...prev, found.n]);\n    setGrilleSelectedCell(null);\n    setAnswer('');\n    setError(null);\n    const filled = nextCells.filter((c) => c).length;\n    if (filled === 9) {\n      const elapsed = game.started_at ? Date.now() - new Date(game.started_at).getTime() : null;\n      setSolved(true);\n      submitResult({ foundCount: 9, elapsedMs: elapsed, solved: true });\n    }\n  };\n\n  const submitGuess = () => {\n    if (gameType === 'main') submitMainGuess();\n    else if (gameType === 'club') submitClubGuess();\n    else submitListeGuess();\n  };\n\n  const withBack = (node: React.ReactElement, opts?: { hideBack?: boolean }) => (\n    <View style={{ flex: 1 }}>\n      {node}\n      {onBack && !opts?.hideBack && (\n        <Pressable\n          onPress={onBack}\n          hitSlop={8}\n          style={{ position: 'absolute', top: insets.top + 14, left: 20, width: 30, height: 30, borderRadius: 999, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n        >\n          <Text style={{ fontFamily: fonts.display, fontSize: 14, color: colors.ink }}>←</Text>\n        </Pressable>\n      )}\n      <Pressable\n        onPress={rules.show}\n        hitSlop={8}\n        style={{ position: 'absolute', top: insets.top + 14, right: 20, width: 30, height: 30, borderRadius: 999, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n      >\n        <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>?</Text>\n      </Pressable>\n      <RulesModal visible={rules.visible} onClose={rules.hide} title={t('rules_group_title')} body={t('rules_group_body')} />\n    </View>\n  );\n\n  if (loading) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center' }}>\n        <ActivityIndicator color={colors.ink} />\n      </View>\n    );\n  }\n\n  // No active game yet. For a 1-on-1 challenge the invite fires\n  // automatically above — this just covers the brief send, or a failure.\n  if (!game && variant === 'duel' && inviteUserId) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center', gap: 14, paddingHorizontal: 20 }}>\n        {createError ? (\n          <>\n            <Text style={{ fontSize: 40 }}>😕</Text>\n            <Text style={{ fontFamily: fonts.display, fontSize: 15, color: colors.ink, textAlign: 'center' }}>{t('duel_invite_error')}</Text>\n            <Pressable\n              onPress={() => {\n                setCreateError(null);\n                autoInviteFiredRef.current = false;\n              }}\n              style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}\n            >\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('group_retry')}</Text>\n            </Pressable>\n          </>\n        ) : (\n          <ActivityIndicator color={colors.ink} />\n        )}\n      </View>\n    );\n  }\n\n  // No active game: create a lobby (Groupe, up to 4 friends).\n  if (!game) {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 60, paddingHorizontal: 20 }}>\n        <Text style={{ fontFamily: fonts.display, fontSize: 22, color: colors.ink }}>{t('group_create_title')}</Text>\n        <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, marginTop: 4 }}>{t('group_create_sub')}</Text>\n\n        {!friends.length && !friendsLoading ? (\n          <Text style={{ fontFamily: fonts.body, fontSize: 13, color: colors.muted, marginTop: 24 }}>{t('group_no_friends')}</Text>\n        ) : (\n          <>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1, marginTop: 20 }}>\n              {t('group_pick_friends')} ({selectedFriendIds.length}/{maxFriends})\n            </Text>\n            <ScrollView style={{ marginTop: 8, maxHeight: 260 }}>\n              {friends.map((f) => {\n                const checked = selectedFriendIds.includes(f.id);\n                return (\n                  <Pressable\n                    key={f.id}\n                    onPress={() => toggleFriend(f.id)}\n                    style={{ flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 10, paddingHorizontal: 12, backgroundColor: checked ? accent.mint : colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, marginBottom: 6 }}\n                  >\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink, flex: 1 }}>{f.display_name}</Text>\n                    <Text style={{ fontFamily: fonts.display, fontSize: 13 }}>{checked ? '✓' : ''}</Text>\n                  </Pressable>\n                );\n              })}\n              {!friends.length && friendsLoading && <ActivityIndicator color={colors.ink} style={{ marginTop: 10 }} />}\n            </ScrollView>\n\n            <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1, marginTop: 16 }}>{t('group_pick_duration')}</Text>\n            <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>\n              {DURATIONS.map((d) => (\n                <Pressable\n                  key={d}\n                  onPress={() => setRoundSeconds(d)}\n                  style={{ flex: 1, paddingVertical: 12, backgroundColor: roundSeconds === d ? accent.coral : colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}\n                >\n                  <Text style={{ fontFamily: fonts.display, fontSize: 13, color: roundSeconds === d ? '#fff' : colors.ink }}>{d}s</Text>\n                </Pressable>\n              ))}\n            </View>\n\n            <Pressable\n              onPress={handleCreate}\n              disabled={!selectedFriendIds.length || busy}\n              style={{ marginTop: 20, paddingVertical: 14, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center', opacity: selectedFriendIds.length ? 1 : 0.5 }}\n            >\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>{t('group_create_button')}</Text>\n            </Pressable>\n          </>\n        )}\n      </View>\n    );\n  }\n\n  // Invited, haven't responded yet.\n  if (game.status === 'lobby' && myRow?.status === 'invited') {\n    const creatorRow = players.find((p) => p.user_id === game.creator_id);\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 16 }}>\n        <Text style={{ fontSize: 40 }}>👥</Text>\n        <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink, textAlign: 'center' }}>\n          {(creatorRow?.display_name || '') + ' ' + t('group_invite_title')}\n        </Text>\n        <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted }}>{game.round_seconds}s · {t('group_invite_sub')}</Text>\n        <View style={{ flexDirection: 'row', gap: 10, marginTop: 8 }}>\n          <Pressable onPress={() => respondInvite(false)} style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink }}>{t('duel_invite_decline')}</Text>\n          </Pressable>\n          <Pressable onPress={() => respondInvite(true)} style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: accent.mint, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink }}>{t('duel_invite_accept')}</Text>\n          </Pressable>\n        </View>\n      </View>\n    );\n  }\n\n  // Lobby: waiting room (Groupe), or a classic direct-duel wait (Duel — no\n  // room/code, just \"waiting for them to answer\" like Grille/XI Type).\n  if (game.status === 'lobby') {\n    const joinedCount = players.filter((p) => p.status === 'joined').length;\n    const listsForDifficulty = listPool === 'xi' ? XI_MATCHES : QUIZ_LISTS.filter((l) => l.difficulty === listDifficulty);\n    const opponentRow = variant === 'duel' ? players.find((p) => p.user_id !== user?.id) : null;\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 60, paddingHorizontal: 20 }}>\n        <ScrollView>\n          {variant === 'duel' ? (\n            <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink }}>\n              {opponentRow?.status === 'declined'\n                ? t('duel_invite_declined_title').replace('{name}', opponentRow.display_name || '')\n                : opponentRow?.status === 'joined'\n                ? (opponentRow.display_name || '') + ' ' + t('duel_opponent_ready_suffix')\n                : t('duel_invite_waiting_title').replace('{name}', opponentRow?.display_name || '')}\n            </Text>\n          ) : (\n            <>\n              <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink }}>\n                {t('group_lobby_title')} {joinedCount}/{players.length}\n              </Text>\n              <View style={{ marginTop: 16, gap: 8 }}>\n                {players.map((p) => (\n                  <View key={p.id} style={{ flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 10, paddingHorizontal: 12, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n                    <Text style={{ fontSize: 16 }}>{p.status === 'joined' ? '✓' : p.status === 'declined' ? '✕' : '○'}</Text>\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink, flex: 1 }}>{p.display_name}</Text>\n                    <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.muted }}>\n                      {p.status === 'joined' ? t('group_status_joined') : p.status === 'declined' ? t('group_status_declined') : t('group_status_waiting')}\n                    </Text>\n                  </View>\n                ))}\n              </View>\n            </>\n          )}\n\n          {isCreator && gameType === 'main' && (\n            <>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted, letterSpacing: 1, marginTop: 20 }}>{t('group_pick_level')}</Text>\n              <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>\n                {(Object.keys(LEVEL_META) as Level[]).map((l) => (\n                  <Pressable\n                    key={l}\n                    onPress={() => setLevel(l)}\n                    style={{ flex: 1, paddingVertical: 12, backgroundColor: level === l ? accent.coral : colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}\n                  >\n                    <Text style={{ fontFamily: fonts.display, fontSize: 12, color: level === l ? '#fff' : colors.ink }}>{LEVEL_META[l].icon} {t(LEVEL_META[l].labelKey)}</Text>\n                  </Pressable>\n                ))}\n              </View>\n              <Pressable\n                onPress={handleStartMain}\n                disabled={joinedCount < 2 || busy}\n                style={{ marginTop: 20, paddingVertical: 14, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center', opacity: joinedCount < 2 ? 0.5 : 1 }}\n              >\n                <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>\n                  {t('group_start_button')} {joinedCount}\n                </Text>\n              </Pressable>\n            </>\n          )}\n\n          {isCreator && gameType === 'club' && (\n            <Pressable\n              onPress={handleStartClub}\n              disabled={joinedCount < 2 || busy}\n              style={{ marginTop: 20, paddingVertical: 14, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center', opacity: joinedCount < 2 ? 0.5 : 1 }}\n            >\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>\n                {t('group_start_button')} {joinedCount}\n              </Text>\n            </Pressable>\n          )}\n\n          {isCreator && gameType === 'liste' && (\n            <>\n              {listPool !== 'xi' && (\n                <>\n                  <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, marginTop: 6 }}>{t('quiz_choose_difficulty')}</Text>\n                  <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>\n                    {(['easy', 'medium', 'hard'] as QuizDifficulty[]).map((d) => (\n                      <Pressable\n                        key={d}\n                        onPress={() => setListDifficulty(d)}\n                        style={{ flex: 1, paddingVertical: 12, backgroundColor: listDifficulty === d ? accent.coral : colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}\n                      >\n                        <Text style={{ fontFamily: fonts.display, fontSize: 12, color: listDifficulty === d ? '#fff' : colors.ink }}>{t(`quiz_difficulty_${d}`)}</Text>\n                      </Pressable>\n                    ))}\n                  </View>\n                </>\n              )}\n              <View style={{ marginTop: 10, gap: 8 }}>\n                {listsForDifficulty.map((l) => (\n                  <Pressable\n                    key={l.id}\n                    onPress={() => handleStartListe(l.id)}\n                    disabled={joinedCount < 2 || busy}\n                    style={{ paddingVertical: 12, paddingHorizontal: 14, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, opacity: joinedCount < 2 ? 0.5 : 1 }}\n                  >\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{l.title}</Text>\n                  </Pressable>\n                ))}\n              </View>\n            </>\n          )}\n\n          {isCreator && gameType === 'grille' && (\n            <Pressable\n              onPress={handleStartGrille}\n              disabled={joinedCount < 2 || busy}\n              style={{ marginTop: 20, paddingVertical: 14, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center', opacity: joinedCount < 2 ? 0.5 : 1 }}\n            >\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>\n                {t('group_start_button')} {joinedCount}\n              </Text>\n            </Pressable>\n          )}\n        </ScrollView>\n\n        <Pressable onPress={() => cancelLobby()} style={{ paddingVertical: 12, alignItems: 'center' }}>\n          <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: colors.muted }}>{t('group_cancel')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // Never responded to the invite before the creator started without us —\n  // no seat to play from, so just let them back out rather than falling\n  // into the active/results branches below as if we were racing too.\n  if (game.status !== 'lobby' && myRow?.status !== 'joined') {\n    return withBack(\n      <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 12 }}>\n        <Text style={{ fontSize: 40 }}>👥</Text>\n        <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.ink, textAlign: 'center' }}>{t('group_missed_title')}</Text>\n        <Pressable onPress={() => leaveFinished()} style={{ paddingVertical: 12, paddingHorizontal: 20, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n          <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('group_leave')}</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  // Active round.\n  if (game.status === 'active') {\n    const contentReady =\n      gameType === 'main' ? !!mysteryPlayer : gameType === 'club' ? !!mysteryClub : gameType === 'grille' ? !!grid : !!mysteryList;\n    if (!contentReady) {\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center' }}>\n          <ActivityIndicator color={colors.ink} />\n        </View>\n      );\n    }\n    const others = players.filter((p) => p.status === 'joined' && p.user_id !== user?.id);\n\n    if (solved || outOfAttempts) {\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14, paddingHorizontal: 20, alignItems: 'center', justifyContent: 'center', gap: 14 }}>\n          <Text style={{ fontSize: 40 }}>{solved ? '✅' : '😔'}</Text>\n          <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink }}>{solved ? t('group_solved_wait') : t('group_out_of_attempts_wait')}</Text>\n          <View style={{ paddingVertical: 6, paddingHorizontal: 14, backgroundColor: colors.track, borderRadius: 999 }}>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 12, color: colors.muted }}>⏱ {secondsLeft}s</Text>\n          </View>\n          <View style={{ flexDirection: 'row', gap: 6, flexWrap: 'wrap', justifyContent: 'center' }}>\n            {others.map((p) => (\n              <View key={p.id} style={{ paddingVertical: 4, paddingHorizontal: 9, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999 }}>\n                <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.ink }}>{p.solved ? '✅' : '⏳'} {p.display_name}</Text>\n              </View>\n            ))}\n          </View>\n        </View>,\n        { hideBack: true }\n      );\n    }\n\n    const timerBar = (\n      <>\n        <View style={{ paddingHorizontal: 20, flexDirection: 'row', justifyContent: 'center', alignItems: 'center' }}>\n          <View style={{ paddingVertical: 4, paddingHorizontal: 10, backgroundColor: secondsLeft <= 10 ? accent.wrongRed : colors.track, borderRadius: 999 }}>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 12, color: secondsLeft <= 10 ? '#fff' : colors.muted }}>⏱ {secondsLeft}s</Text>\n          </View>\n        </View>\n        <View style={{ paddingHorizontal: 20, flexDirection: 'row', gap: 6, flexWrap: 'wrap', justifyContent: 'center', marginTop: 8 }}>\n          {others.map((p) => (\n            <View key={p.id} style={{ paddingVertical: 3, paddingHorizontal: 8, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999 }}>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.ink }}>{p.solved ? '✅' : '⏳'} {p.display_name}</Text>\n            </View>\n          ))}\n        </View>\n      </>\n    );\n\n    const keyboard = (\n      <View style={{ marginTop: 8, gap: 4 }}>\n        {KEY_ROWS_BY_LANG[lang].map((row, ri) => (\n          <View key={ri} style={{ flexDirection: 'row', gap: 4 }}>\n            {ri === 2 && <View style={{ flex: 0.5 }} />}\n            {row.split('').map((l) => (\n              <Pressable\n                key={l}\n                onPress={() => setAnswer(answer + l)}\n                style={{ flex: 1, height: 36, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}\n              >\n                <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{l}</Text>\n              </Pressable>\n            ))}\n            {ri === 2 && <View style={{ flex: 0.5 }} />}\n          </View>\n        ))}\n        <View style={{ flexDirection: 'row', gap: 4 }}>\n          <Pressable onPress={() => setAnswer(answer.slice(0, -1))} style={{ flex: 1.4, height: 36, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{t('game_backspace')}</Text>\n          </Pressable>\n          <Pressable onPress={() => setAnswer(answer + ' ')} style={{ flex: 3, height: 36, borderRadius: 6, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: colors.ink }}>{t('game_space')}</Text>\n          </Pressable>\n        </View>\n      </View>\n    );\n\n    if (gameType === 'main' && mysteryPlayer) {\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n          {timerBar}\n          <ScrollView contentContainerStyle={{ paddingHorizontal: 20, paddingTop: 10, gap: 5 }}>\n            {mysteryPlayer.clubs.map((c, i) => {\n              const rev = i < revealed;\n              if (rev) {\n                return (\n                  <RevealCard key={i}>\n                    <HardShadowBox bg={colors.card} radius={12} offset={3} style={{ marginBottom: 5 }}>\n                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, padding: 6 }}>\n                        <ClubShield name={c} size={36} />\n                        <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink, flex: 1 }}>{c}</Text>\n                      </View>\n                    </HardShadowBox>\n                  </RevealCard>\n                );\n              }\n              return (\n                <View key={i} style={{ flexDirection: 'row', alignItems: 'center', gap: 8, padding: 6, backgroundColor: colors.track, borderWidth: 2, borderColor: 'rgba(0,0,0,.2)', borderStyle: 'dashed', borderRadius: 12, marginBottom: 5 }}>\n                  <View style={{ width: 36, height: 36, borderRadius: 8, backgroundColor: colors.card, alignItems: 'center', justifyContent: 'center' }}>\n                    <Text style={{ fontFamily: fonts.display, fontSize: 14, color: colors.muted }}>?</Text>\n                  </View>\n                </View>\n              );\n            })}\n          </ScrollView>\n          {wrongList.length > 0 && (\n            <View style={{ paddingHorizontal: 20, paddingTop: 6, flexDirection: 'row', gap: 5, flexWrap: 'wrap' }}>\n              {wrongList.map((w, i) => (\n                <View key={i} style={{ paddingVertical: 3, paddingHorizontal: 9, backgroundColor: accent.wrongRed, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999 }}>\n                  <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 9, color: colors.ink }}>✕ {w}</Text>\n                </View>\n              ))}\n            </View>\n          )}\n          <View style={{ paddingHorizontal: 20, paddingTop: 8, paddingBottom: Math.max(12, insets.bottom + 8) }}>\n            <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, paddingVertical: 10, paddingHorizontal: 12 }}>\n              <Text numberOfLines={1} style={{ fontFamily: fonts.displayBold, fontSize: 14, color: answer ? colors.ink : colors.muted }}>{answer || t('game_input_placeholder')}</Text>\n            </View>\n            {keyboard}\n            <Pressable onPress={submitGuess} style={{ marginTop: 8, paddingVertical: 12, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 1, textTransform: 'uppercase' }}>{t('game_send')}</Text>\n            </Pressable>\n          </View>\n        </View>,\n        { hideBack: true }\n      );\n    }\n\n    if (gameType === 'club' && mysteryClub) {\n      const revealFraction = 0.15 + 0.85 * (clubGuesses.length / MAX_GUESSES);\n      const clubNames = Object.keys(CLUB_DATA);\n      const suggestions =\n        answer.trim().length >= 2\n          ? clubNames.filter((n) => stripAcc(n.toLowerCase()).includes(stripAcc(answer.trim().toLowerCase()))).slice(0, 5)\n          : [];\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n          {timerBar}\n          <View style={{ alignItems: 'center', paddingVertical: 12 }}>\n            <Crest name={mysteryClub} revealFraction={revealFraction} />\n          </View>\n          <ScrollView contentContainerStyle={{ paddingHorizontal: 20, paddingBottom: 8 }}>\n            {clubGuesses.map((g) => (\n              <ClubGuessChips key={g.name} row={g} />\n            ))}\n          </ScrollView>\n          <View style={{ paddingHorizontal: 20, paddingTop: 8, paddingBottom: Math.max(12, insets.bottom + 8) }}>\n            <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, paddingVertical: 10, paddingHorizontal: 12 }}>\n              <Text numberOfLines={1} style={{ fontFamily: fonts.displayBold, fontSize: 14, color: answer ? colors.ink : colors.muted }}>{answer || t('club_answer_placeholder')}</Text>\n            </View>\n            {suggestions.length > 0 && (\n              <View style={{ marginTop: 6, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, overflow: 'hidden' }}>\n                {suggestions.map((s) => (\n                  <Pressable key={s} onPress={() => setAnswer(s)} style={{ paddingVertical: 8, paddingHorizontal: 14, borderBottomWidth: 1, borderBottomColor: 'rgba(0,0,0,.06)' }}>\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{s}</Text>\n                  </Pressable>\n                ))}\n              </View>\n            )}\n            {error && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: accent.coral, marginTop: 6 }}>{error}</Text>}\n            {keyboard}\n            <Pressable onPress={submitGuess} style={{ marginTop: 8, paddingVertical: 12, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 1, textTransform: 'uppercase' }}>{t('game_send')}</Text>\n            </Pressable>\n          </View>\n        </View>,\n        { hideBack: true }\n      );\n    }\n\n    if (gameType === 'liste' && mysteryList) {\n      const listeSuggestions =\n        answer.trim().length >= 2\n          ? mysteryList.players\n              .filter((_, i) => !foundIndexes.includes(i))\n              .filter((p) => stripAcc(playerFull(p).toLowerCase()).includes(stripAcc(answer.trim().toLowerCase())))\n              .slice(0, 5)\n          : [];\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n          {timerBar}\n          <Text style={{ textAlign: 'center', fontFamily: fonts.displayBold, fontSize: 14, color: colors.ink, marginTop: 8 }}>\n            {mysteryList.title} · {foundIndexes.length}/{mysteryList.players.length}\n          </Text>\n          {listPool === 'xi' ? (\n            <ScrollView contentContainerStyle={{ paddingHorizontal: 20, paddingTop: 10 }}>\n              <XIPitch players={mysteryList.players} foundIndexes={foundIndexes} />\n            </ScrollView>\n          ) : (\n            <ScrollView contentContainerStyle={{ paddingHorizontal: 20, paddingTop: 10, flexDirection: 'row', flexWrap: 'wrap', gap: 6 }}>\n              {mysteryList.players.map((p, i) => {\n                const found = foundIndexes.includes(i);\n                const photo = found ? playerPhoto(p) : undefined;\n                return (\n                  <View\n                    key={i}\n                    style={{ flexDirection: 'row', alignItems: 'center', gap: 6, paddingVertical: 6, paddingHorizontal: 10, borderRadius: 999, backgroundColor: found ? accent.mint : colors.track, borderWidth: 1.5, borderColor: colors.border }}\n                  >\n                    {photo && <PlayerPortrait name={photo} size={18} variant=\"avatar\" />}\n                    <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.ink }}>{found ? playerFull(p) : '?'}</Text>\n                  </View>\n                );\n              })}\n            </ScrollView>\n          )}\n          <View style={{ paddingHorizontal: 20, paddingTop: 8, paddingBottom: Math.max(12, insets.bottom + 8) }}>\n            <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, paddingVertical: 10, paddingHorizontal: 12 }}>\n              <Text numberOfLines={1} style={{ fontFamily: fonts.displayBold, fontSize: 14, color: answer ? colors.ink : colors.muted }}>{answer || t('game_input_placeholder')}</Text>\n            </View>\n            {listeSuggestions.length > 0 && (\n              <View style={{ marginTop: 6, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, overflow: 'hidden' }}>\n                {listeSuggestions.map((s) => (\n                  <Pressable key={playerFull(s)} onPress={() => setAnswer(playerFull(s))} style={{ paddingVertical: 8, paddingHorizontal: 14, borderBottomWidth: 1, borderBottomColor: 'rgba(0,0,0,.06)' }}>\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{playerFull(s)}</Text>\n                  </Pressable>\n                ))}\n              </View>\n            )}\n            {error && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: accent.coral, marginTop: 6 }}>{error}</Text>}\n            {keyboard}\n            <Pressable onPress={submitGuess} style={{ marginTop: 8, paddingVertical: 12, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 12, alignItems: 'center' }}>\n              <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 1, textTransform: 'uppercase' }}>{t('game_send')}</Text>\n            </Pressable>\n          </View>\n        </View>,\n        { hideBack: true }\n      );\n    }\n\n    if (gameType === 'grille' && grid) {\n      const filledCount = grilleCells.filter((c) => c).length;\n      const cellSuggestions =\n        answer.trim().length >= 2\n          ? PLAYERS.filter((p) => stripAcc(p.n.toLowerCase()).includes(stripAcc(answer.trim().toLowerCase()))).slice(0, 5)\n          : [];\n      return withBack(\n        <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 14 }}>\n          {timerBar}\n          <Text style={{ textAlign: 'center', fontFamily: fonts.displayBold, fontSize: 14, color: colors.ink, marginTop: 8 }}>\n            {filledCount}/9\n          </Text>\n          <View style={{ padding: 20 }}>\n            <View style={{ flexDirection: 'row' }}>\n              <View style={{ width: 70 }} />\n              {grid.cols.map((c, i) => (\n                <View key={i} style={{ flex: 1, alignItems: 'center', paddingBottom: 6, gap: 3 }}>\n                  {c.type === 'nat' && <Text style={{ fontSize: 24 }}>{flagEmoji(c.value)}</Text>}\n                  {c.type === 'club' && <ClubShield name={c.value} size={30} />}\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 9, color: colors.ink, textAlign: 'center' }}>{criterionLabel(c, t)}</Text>\n                </View>\n              ))}\n            </View>\n            {grid.rows.map((r, ri) => (\n              <View key={ri} style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6 }}>\n                <View style={{ width: 70, paddingRight: 6, alignItems: 'center', gap: 3 }}>\n                  {r.type === 'club' && <ClubShield name={r.value} size={30} />}\n                  <Text style={{ fontFamily: fonts.displayBold, fontSize: 9, color: colors.ink, textAlign: 'center' }} numberOfLines={2}>{criterionLabel(r, t)}</Text>\n                </View>\n                {grid.cols.map((_, ci) => {\n                  const index = ri * 3 + ci;\n                  const cellName = grilleCells[index];\n                  return (\n                    <Pressable\n                      key={ci}\n                      onPress={() => {\n                        if (cellName) return;\n                        setGrilleSelectedCell(index);\n                        setAnswer('');\n                        setError(null);\n                      }}\n                      style={{ flex: 1, aspectRatio: 1, marginHorizontal: 3, borderRadius: 10, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center', backgroundColor: cellName ? accent.mint : colors.card, padding: 4 }}\n                    >\n                      {cellName ? (\n                        <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 9, color: '#1a1a1a', textAlign: 'center' }} numberOfLines={2}>{cellName}</Text>\n                      ) : (\n                        <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.muted }}>+</Text>\n                      )}\n                    </Pressable>\n                  );\n                })}\n              </View>\n            ))}\n          </View>\n\n          <Modal visible={grilleSelectedCell !== null} transparent animationType=\"fade\" onRequestClose={() => setGrilleSelectedCell(null)}>\n            <Pressable style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.45)', justifyContent: 'flex-end' }} onPress={() => setGrilleSelectedCell(null)}>\n              <Pressable style={{ backgroundColor: colors.bg, borderTopWidth: 2.5, borderColor: colors.border, borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: 20, paddingBottom: Math.max(20, insets.bottom + 12) }}>\n                <View style={{ backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, paddingVertical: 12, paddingHorizontal: 14 }}>\n                  <Text numberOfLines={1} style={{ fontFamily: fonts.displayBold, fontSize: 14, color: answer ? colors.ink : colors.muted }}>\n                    {answer || t('duel_answer_placeholder')}\n                  </Text>\n                </View>\n                {cellSuggestions.length > 0 && (\n                  <View style={{ marginTop: 6, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12, overflow: 'hidden' }}>\n                    {cellSuggestions.map((s) => (\n                      <Pressable key={s.n} onPress={() => setAnswer(s.n)} style={{ paddingVertical: 9, paddingHorizontal: 14, borderBottomWidth: 1, borderBottomColor: 'rgba(0,0,0,.06)' }}>\n                        <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>{s.n}</Text>\n                      </Pressable>\n                    ))}\n                  </View>\n                )}\n                {error && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 11, color: accent.coral, marginTop: 8 }}>{error}</Text>}\n                {keyboard}\n                <Pressable onPress={submitGrilleCell} style={{ marginTop: 12, paddingVertical: 12, backgroundColor: accent.coral, borderRadius: 12, alignItems: 'center' }}>\n                  <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff' }}>{t('duel_validate')}</Text>\n                </Pressable>\n              </Pressable>\n            </Pressable>\n          </Modal>\n        </View>,\n        { hideBack: true }\n      );\n    }\n  }\n\n  // Finished: results.\n  const ranked = players\n    .filter((p) => p.status === 'joined')\n    .slice()\n    .sort((a, b) => {\n      if (gameType === 'liste') return b.found_count - a.found_count;\n      if (a.solved && b.solved) return (a.elapsed_ms || 0) - (b.elapsed_ms || 0);\n      if (a.solved) return -1;\n      if (b.solved) return 1;\n      if (gameType === 'grille') return b.found_count - a.found_count;\n      return b.attempts - a.attempts;\n    });\n  const medals = ['🥇', '🥈', '🥉'];\n  const revealLabel = gameType === 'main' ? game.mystery_player : gameType === 'club' ? game.mystery_club : null;\n\n  return withBack(\n    <View style={{ flex: 1, backgroundColor: colors.bg, paddingTop: insets.top + 60, paddingHorizontal: 20 }}>\n      <ScrollView>\n        <Text style={{ fontFamily: fonts.display, fontSize: 22, color: colors.ink }}>{t('group_results_title')}</Text>\n        {revealLabel && (\n          <Text style={{ fontFamily: fonts.body, fontSize: 12, color: colors.muted, marginTop: 4 }}>\n            {t('group_results_sub')} {revealLabel}\n          </Text>\n        )}\n        {lastReward > 0 && (\n          <View style={{ marginTop: 12, alignSelf: 'flex-start', paddingVertical: 6, paddingHorizontal: 12, backgroundColor: accent.mint, borderWidth: 2, borderColor: colors.border, borderRadius: 999 }}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink }}>+{lastReward} 💎</Text>\n          </View>\n        )}\n        <View style={{ marginTop: 16, gap: 8 }}>\n          {ranked.map((p, i) => (\n            <View key={p.id} style={{ flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 10, paddingHorizontal: 12, backgroundColor: p.user_id === user?.id ? accent.mint : colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n              <Text style={{ fontSize: 16 }}>\n                {gameType === 'liste'\n                  ? p.found_count > 0 && medals[i]\n                    ? medals[i]\n                    : p.found_count > 0\n                    ? '✅'\n                    : '—'\n                  : p.solved && medals[i]\n                  ? medals[i]\n                  : p.solved\n                  ? '✅'\n                  : '—'}\n              </Text>\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 13, color: colors.ink, flex: 1 }}>{p.display_name}</Text>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted }}>\n                {gameType === 'liste'\n                  ? `${p.found_count} ${t('group_found_short')}`\n                  : gameType === 'grille'\n                  ? p.solved\n                    ? `${Math.round((p.elapsed_ms || 0) / 1000)}s`\n                    : `${p.found_count}/9`\n                  : p.solved\n                  ? `${p.attempts} ${t('group_attempts_short')} · ${Math.round((p.elapsed_ms || 0) / 1000)}s`\n                  : t('group_not_found')}\n              </Text>\n            </View>\n          ))}\n        </View>\n      </ScrollView>\n      <Pressable onPress={() => recordRoundPlayed(leaveFinished)} style={{ marginVertical: 12, paddingVertical: 14, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 14, alignItems: 'center' }}>\n        <Text style={{ fontFamily: fonts.display, fontSize: 13, color: '#fff', letterSpacing: 0.5, textTransform: 'uppercase' }}>{t('group_leave')}</Text>\n      </Pressable>\n    </View>\n  );\n}\n");
write("src/screens/ProfilScreen.tsx", "import React, { useCallback, useState } from 'react';\nimport { ActivityIndicator, Alert, Image, Pressable, ScrollView, Text, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { useFocusEffect, useNavigation } from '@react-navigation/native';\nimport { useTheme } from '../theme/ThemeContext';\nimport { useI18n } from '../i18n/i18n';\nimport { useDiamonds } from '../state/diamonds';\nimport { STREAK_FREEZE_COST, useStats } from '../state/stats';\nimport { useAuth } from '../state/auth';\nimport { useFriends } from '../state/friends';\nimport { useGameHistory } from '../state/appStats';\nimport { useAvatar } from '../state/avatar';\nimport { pickAndUploadAvatar } from '../lib/avatarUpload';\nimport { BADGES } from '../lib/badges';\nimport AvatarFrame from '../components/AvatarFrame';\nimport { useSolvedPlayers } from '../state/solvedPlayers';\nimport { PLAYERS } from '../data/players';\n\nfunction formatRelativeDay(iso: string, t: (k: string) => string): string {\n  const day = iso.slice(0, 10);\n  const today = new Date().toISOString().slice(0, 10);\n  if (day === today) return t('profil_today');\n  const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);\n  if (day === yesterday) return t('profil_yesterday');\n  const diffDays = Math.round((new Date(today).getTime() - new Date(day).getTime()) / 86400000);\n  return `-${diffDays}${t('profil_days_ago_suffix')}`;\n}\n\nexport default function ProfilScreen() {\n  const { colors, accent, fonts } = useTheme();\n  const { t, tArray } = useI18n();\n  const { diamonds } = useDiamonds();\n  const { stats, derived, buyStreakFreeze } = useStats();\n  const [freezeMessage, setFreezeMessage] = useState<string | null>(null);\n  const { user } = useAuth();\n  const { friends, refresh: refreshFriends } = useFriends();\n  const { history, refresh: refreshHistory } = useGameHistory(5);\n  const { avatarUrl, setAvatarUrl, equippedFrame } = useAvatar();\n  const { solvedPlayers } = useSolvedPlayers();\n  const collectionCount = PLAYERS.filter((p) => solvedPlayers.has(p.n)).length;\n  const [avatarUploading, setAvatarUploading] = useState(false);\n  const insets = useSafeAreaInsets();\n  const navigation = useNavigation<any>();\n  const username = user?.user_metadata?.display_name || user?.email?.split('@')[0] || 'Vous';\n  const ordinals = tArray('ordinals');\n\n  const onChangeAvatar = async () => {\n    if (!user || avatarUploading) return;\n    setAvatarUploading(true);\n    const { url, error } = await pickAndUploadAvatar(user.id);\n    setAvatarUploading(false);\n    if (url) {\n      setAvatarUrl(url);\n    } else if (error === 'permission_denied') {\n      Alert.alert(t('profil_avatar_error_title'), t('profil_avatar_permission_denied'));\n    } else if (error) {\n      // Storage upload failures come back as a raw debug string (status\n      // code, byte size) meant for logs, not players — never shown as-is.\n      Alert.alert(t('profil_avatar_error_title'), t('error_generic'));\n    }\n  };\n\n  // Profil stays mounted in the tab navigator, so without this the history\n  // and friend count would keep showing whatever they were on first load —\n  // stale after finishing a game or adding a friend elsewhere.\n  useFocusEffect(\n    useCallback(() => {\n      refreshHistory();\n      refreshFriends();\n    }, [refreshHistory, refreshFriends])\n  );\n  const badgeStates = BADGES.map((b) => ({ ...b, unlocked: b.isUnlocked(stats, derived.level) }));\n  const unlockedCount = badgeStates.filter((b) => b.unlocked).length;\n\n  return (\n    <View style={{ flex: 1, backgroundColor: colors.bg }}>\n      <View pointerEvents=\"none\" style={{ position: 'absolute', top: -30, right: -30, width: 180, height: 180, backgroundColor: accent.coral, borderRadius: 999, opacity: 0.08 }} />\n      <ScrollView contentContainerStyle={{ paddingTop: insets.top + 6, paddingBottom: 24 }}>\n        <View style={{ paddingHorizontal: 20, alignItems: 'flex-end' }}>\n          <Pressable onPress={() => navigation.getParent()?.navigate('Settings')}>\n            <Text style={{ fontFamily: fonts.displayBold, fontSize: 18, color: colors.ink }}>⚙</Text>\n          </Pressable>\n        </View>\n\n        <View style={{ paddingHorizontal: 20, alignItems: 'center' }}>\n          <Pressable onPress={onChangeAvatar} disabled={avatarUploading}>\n            <AvatarFrame frameId={equippedFrame} size={100}>\n              <View\n                style={{\n                  width: 100, height: 100, borderRadius: 999, backgroundColor: accent.yellow,\n                  borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center', overflow: 'hidden',\n                }}\n              >\n                {avatarUploading ? (\n                  <ActivityIndicator color={colors.ink} />\n                ) : avatarUrl ? (\n                  <Image source={{ uri: avatarUrl }} style={{ width: '100%', height: '100%' }} />\n                ) : (\n                  <Text style={{ fontFamily: fonts.display, fontSize: 40, color: colors.ink }}>{username.slice(0, 1).toUpperCase()}</Text>\n                )}\n              </View>\n            </AvatarFrame>\n            <View\n              style={{\n                position: 'absolute', bottom: 0, right: 0, width: 30, height: 30, borderRadius: 999,\n                backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.bg, alignItems: 'center', justifyContent: 'center',\n              }}\n            >\n              <Text style={{ fontSize: 13 }}>📷</Text>\n            </View>\n          </Pressable>\n          <Text style={{ fontFamily: fonts.display, fontSize: 22, color: colors.ink, marginTop: 14, letterSpacing: -0.4 }}>{username}</Text>\n          <View style={{ flexDirection: 'row', gap: 6, marginTop: 6 }}>\n            <View style={{ paddingVertical: 3, paddingHorizontal: 9, backgroundColor: colors.border, borderRadius: 999 }}>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: accent.yellow, letterSpacing: 1 }}>LVL {derived.level}</Text>\n            </View>\n            <View style={{ paddingVertical: 3, paddingHorizontal: 9, backgroundColor: colors.card, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999 }}>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.ink }}>@{username}</Text>\n            </View>\n          </View>\n          <View style={{ flexDirection: 'row', gap: 8, marginTop: 12 }}>\n            <Pressable\n              onPress={() => navigation.navigate('Friends')}\n              style={{ paddingVertical: 8, paddingHorizontal: 16, backgroundColor: accent.blue, borderWidth: 2, borderColor: colors.border, borderRadius: 999 }}\n            >\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: '#fff' }}>🏆 {t('profil_my_friends')} · {friends.length}</Text>\n            </Pressable>\n            <Pressable\n              onPress={() => navigation.getParent()?.navigate('Collection')}\n              style={{ paddingVertical: 8, paddingHorizontal: 16, backgroundColor: accent.coral, borderWidth: 2, borderColor: colors.border, borderRadius: 999 }}\n            >\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 11, color: '#fff' }}>🃏 {t('profil_my_collection')} · {collectionCount}/{PLAYERS.length}</Text>\n            </Pressable>\n          </View>\n        </View>\n\n        <View style={{ paddingHorizontal: 20, paddingTop: 14 }}>\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted }}>LVL {derived.level} · {derived.xpIntoLevel} XP</Text>\n            <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: colors.muted }}>LVL {derived.level + 1} · {derived.xpForNextLevel}</Text>\n          </View>\n          <View style={{ height: 10, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 999, overflow: 'hidden', marginTop: 4 }}>\n            <View style={{ width: `${Math.round(derived.levelProgress * 100)}%`, height: '100%', backgroundColor: accent.coral }} />\n          </View>\n        </View>\n\n        <View style={{ paddingHorizontal: 20, paddingTop: 14, flexDirection: 'row', gap: 8 }}>\n          {[\n            { bg: colors.card, val: String(stats.solves), label: t('profil_solves'), onPress: undefined },\n            { bg: accent.mint, val: `🔥 ${stats.currentStreak}`, label: t('profil_streak'), onPress: undefined },\n            { bg: accent.pink, val: `💎${diamonds}`, label: t('profil_gems'), onPress: () => navigation.getParent()?.navigate('Shop') },\n          ].map((s, i) => {\n            const Wrapper = s.onPress ? Pressable : View;\n            return (\n              <Wrapper key={i} onPress={s.onPress} style={{ flex: 1, backgroundColor: s.bg, borderWidth: 2, borderColor: colors.border, borderRadius: 12, padding: 9, alignItems: 'center' }}>\n                <Text style={{ fontFamily: fonts.display, fontSize: 20, color: colors.ink }}>{s.val}</Text>\n                <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.muted, letterSpacing: 0.8 }}>{s.label}</Text>\n              </Wrapper>\n            );\n          })}\n        </View>\n\n        <View style={{ paddingHorizontal: 20, paddingTop: 8 }}>\n          <Pressable\n            onPress={() => {\n              const { error } = buyStreakFreeze();\n              setFreezeMessage(error === 'not_enough_diamonds' ? t('profil_freeze_not_enough') : t('profil_freeze_bought'));\n            }}\n            style={{ flexDirection: 'row', alignItems: 'center', gap: 10, padding: 10, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}\n          >\n            <Text style={{ fontSize: 18 }}>🧊</Text>\n            <View style={{ flex: 1 }}>\n              <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink }}>{t('profil_freeze_title')} × {stats.streakFreezes}</Text>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.muted, marginTop: 1 }}>{t('profil_freeze_subtitle')}</Text>\n            </View>\n            <View style={{ paddingVertical: 4, paddingHorizontal: 9, backgroundColor: accent.mint, borderWidth: 1.5, borderColor: colors.border, borderRadius: 999 }}>\n              <Text style={{ fontFamily: fonts.mono, fontSize: 10, color: '#1a1a1a' }}>💎{STREAK_FREEZE_COST}</Text>\n            </View>\n          </Pressable>\n          {freezeMessage && <Text style={{ fontFamily: fonts.bodySemibold, fontSize: 10, color: colors.muted, marginTop: 4 }}>{freezeMessage}</Text>}\n        </View>\n\n        <View style={{ paddingHorizontal: 20, paddingTop: 14 }}>\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 6 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink }}>{t('profil_badges')} · {unlockedCount}/{badgeStates.length}</Text>\n          </View>\n          <View style={{ flexDirection: 'row', gap: 6, flexWrap: 'wrap', marginBottom: 14 }}>\n            {badgeStates.map((b) =>\n              b.unlocked ? (\n                <View key={b.id} style={{ width: 44, height: 44, borderRadius: 11, backgroundColor: b.bg, borderWidth: 2, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n                  <Text style={{ fontSize: 20 }}>{b.icon}</Text>\n                </View>\n              ) : (\n                <View key={b.id} style={{ width: 44, height: 44, borderRadius: 11, backgroundColor: colors.card, borderWidth: 2, borderColor: colors.muted, borderStyle: 'dashed', alignItems: 'center', justifyContent: 'center' }}>\n                  <Text style={{ fontFamily: fonts.display, fontSize: 16, color: colors.muted }}>?</Text>\n                </View>\n              )\n            )}\n          </View>\n\n          <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 6 }}>\n            <Text style={{ fontFamily: fonts.display, fontSize: 13, color: colors.ink }}>{t('profil_history')}</Text>\n          </View>\n          {history.length === 0 ? (\n            <Text style={{ fontFamily: fonts.mono, fontSize: 11, color: colors.muted, paddingVertical: 8 }}>{t('profil_no_history')}</Text>\n          ) : (\n            <View style={{ gap: 5 }}>\n              {history.map((h) => (\n                <View key={h.id} style={{ flexDirection: 'row', alignItems: 'center', gap: 9, padding: 8, backgroundColor: h.won ? colors.card : accent.wrongRed, borderWidth: 2, borderColor: colors.border, borderRadius: 12 }}>\n                  <View style={{ width: 28, height: 28, borderRadius: 8, backgroundColor: h.won ? accent.mint : colors.card, borderWidth: 1.5, borderColor: colors.border, alignItems: 'center', justifyContent: 'center' }}>\n                    <Text style={{ fontFamily: fonts.display, fontSize: 12 }}>{h.won ? '✓' : '✕'}</Text>\n                  </View>\n                  <View style={{ flex: 1 }}>\n                    <Text style={{ fontFamily: fonts.displayBold, fontSize: 12, color: colors.ink }}>{h.player_name}</Text>\n                    <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.muted }}>\n                      {h.won\n                        ? `${t('profil_found_at')} ${ordinals[(h.attempt || 1) - 1] || h.attempt} ${t('profil_club')} · +${h.reward_diamonds} 💎`\n                        : t('profil_missed')}\n                    </Text>\n                  </View>\n                  <Text style={{ fontFamily: fonts.mono, fontSize: 9, color: colors.muted }}>{formatRelativeDay(h.created_at, t)}</Text>\n                </View>\n              ))}\n            </View>\n          )}\n        </View>\n      </ScrollView>\n    </View>\n  );\n}\n");
